base:
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:var(--font-body);color:var(--c-ink);background:var(--c-bg);line-height:1.6;font-size:16px;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
.sec{padding:88px 0}
.sec.alt{background:var(--c-surface)}
.sec.dark{background:var(--c-dark);color:var(--c-on-dark)}
.hd{font-family:var(--font-head);font-weight:var(--head-weight);text-transform:var(--head-case);letter-spacing:var(--head-track);line-height:1.12}
.eyebrow{display:inline-block;font-size:13px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--c-accent)}
.sec-head{margin-bottom:44px;max-width:680px}
.sec-head.center{margin-left:auto;margin-right:auto;text-align:center}
.sec-title{font-size:clamp(28px,3.2vw,42px);margin:10px 0 14px}
.sec-sub{color:var(--c-muted);font-size:17px}
.dark .sec-sub{color:inherit;opacity:.72}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 26px;border-radius:var(--radius-btn);background:var(--c-accent);color:var(--c-on-accent);font-weight:700;font-size:15px;border:2px solid var(--c-accent);cursor:pointer;transition:transform .2s,box-shadow .2s}
.btn:hover{transform:translateY(-2px);box-shadow:0 8px 20px rgba(0,0,0,.15)}
.btn.ghost{background:transparent;color:inherit;border-color:currentColor}
.link{font-weight:700;color:var(--c-accent)}
.ph{position:relative;overflow:hidden;border-radius:var(--radius);background:
  radial-gradient(120% 90% at 85% 10%,rgba(255,255,255,.35),transparent 55%),
  repeating-linear-gradient(135deg,rgba(255,255,255,.06) 0 2px,transparent 2px 14px),
  linear-gradient(135deg,var(--img-a),var(--img-b))}
.ph::after{content:attr(data-label);position:absolute;left:12px;bottom:10px;font-size:12px;line-height:1.4;color:#fff;background:rgba(0,0,0,.38);padding:3px 9px;border-radius:4px;letter-spacing:0;text-transform:none;font-weight:500}
.card{background:var(--c-card);border:1px solid var(--c-line);border-radius:var(--radius)}
.ico{width:46px;height:46px;border-radius:calc(var(--radius) + 2px);background:color-mix(in srgb,var(--c-accent) 14%,transparent);color:var(--c-accent);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:15px;flex:none}
.grid{display:grid;gap:24px}
.g2{grid-template-columns:repeat(2,1fr)}.g3{grid-template-columns:repeat(3,1fr)}.g4{grid-template-columns:repeat(4,1fr)}
@media(max-width:860px){.g3,.g4{grid-template-columns:repeat(2,1fr)}.sec{padding:60px 0}}
@media(max-width:560px){.g2,.g3,.g4{grid-template-columns:1fr}}

blocks.css:
.b-h3{padding:80px 0 72px;text-align:center;background:radial-gradient(70% 60% at 50% 70%,var(--c-surface),var(--c-bg))}
.b-h3 h1{font-size:clamp(34px,4.6vw,60px);max-width:860px;margin:14px auto 16px}
.b-h3 p{font-size:18px;color:var(--c-muted);max-width:600px;margin:0 auto}
.b-h3 .acts{display:flex;gap:14px;justify-content:center;margin:28px 0 44px;flex-wrap:wrap}
.b-h3 .img{max-width:620px;aspect-ratio:16/9;margin:0 auto}
.b-h3 .specs{display:grid;grid-template-columns:repeat(4,1fr);max-width:820px;margin:40px auto 0;border-top:1px solid var(--c-line)}
.b-h3 .specs div{padding:20px 8px}
.b-h3 .specs b{display:block;font-size:20px;font-family:var(--font-head)}
.b-h3 .specs span{font-size:13px;color:var(--c-muted)}
@media(max-width:560px){.b-h3 .specs{grid-template-columns:1fr 1fr}}

.b-h6{position:relative;background:var(--c-dark);color:var(--c-on-dark);padding:88px 0 40px;overflow:hidden}
.b-h6 .grid-bg{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.06) 1px,transparent 1px);background-size:48px 48px;mask-image:radial-gradient(70% 70% at 70% 30%,#000,transparent)}
.b-h6 .grid-bg::after{content:"";position:absolute;width:520px;height:520px;right:-80px;top:-160px;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--c-accent) 45%,transparent),transparent 65%)}
.b-h6 .wrap{position:relative}
.b-h6 .top{display:grid;grid-template-columns:1.1fr 1fr;gap:56px;align-items:center}
.b-h6 h1{font-size:clamp(34px,4.6vw,60px);margin:14px 0 18px}
.b-h6 p{font-size:18px;opacity:.75}
.b-h6 .acts{display:flex;gap:14px;margin-top:30px;flex-wrap:wrap}
.b-h6 .img{aspect-ratio:4/3;box-shadow:0 0 0 1px rgba(255,255,255,.12),0 30px 60px rgba(0,0,0,.4)}
.b-h6 .stats{display:grid;grid-template-columns:repeat(4,1fr);margin-top:64px;border-top:1px solid rgba(255,255,255,.14)}
.b-h6 .stats div{padding:24px 0}
.b-h6 .stats b{display:block;font-size:30px;font-family:var(--font-head);color:var(--c-accent)}
.b-h6 .stats span{font-size:14px;opacity:.7}
@media(max-width:860px){.b-h6 .top{grid-template-columns:1fr}.b-h6 .stats{grid-template-columns:1fr 1fr}}

.b-c3 .wrap{display:grid;grid-template-columns:240px 1fr;gap:32px;align-items:start}
.b-c3 aside{padding:22px;position:sticky;top:96px}
.b-c3 aside>b{display:block;font-size:17px;margin-bottom:8px}
.b-c3 .grp{border-top:1px solid var(--c-line);padding:14px 0 6px}
.b-c3 .grp span{display:block;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--c-muted);margin-bottom:8px}
.b-c3 label{display:flex;align-items:center;gap:10px;font-size:15px;margin-bottom:8px;cursor:pointer}
.b-c3 label i{width:16px;height:16px;border:2px solid var(--c-line);border-radius:3px}
.b-c3 label i.on{background:var(--c-accent);border-color:var(--c-accent)}
.b-c3 .bar{display:flex;justify-content:space-between;font-size:14px;color:var(--c-muted);margin-bottom:18px}
.b-c3 .p{display:block;padding:14px;transition:.25s}
.b-c3 .p:hover{border-color:var(--c-accent)}
.b-c3 .p .ph{aspect-ratio:1}
.b-c3 .p b{display:block;margin:14px 0 2px}
.b-c3 .p small{color:var(--c-muted)}
@media(max-width:860px){.b-c3 .wrap{grid-template-columns:1fr}.b-c3 aside{position:static}}

.b-c4 .tw{overflow-x:auto;border:1px solid var(--c-line);border-radius:var(--radius)}
.b-c4 table{border-collapse:collapse;width:100%;min-width:680px;font-size:15px}
.b-c4 th,.b-c4 td{padding:16px 18px;border-bottom:1px solid var(--c-line);text-align:center}
.b-c4 th{font-family:var(--font-head);font-size:16px;background:var(--c-surface)}
.b-c4 td:first-child,.b-c4 th:first-child{text-align:left;font-weight:700;position:sticky;left:0;background:var(--c-surface)}
.b-c4 .hl{background:color-mix(in srgb,var(--c-accent) 9%,var(--c-card))}
.b-c4 th.hl{background:color-mix(in srgb,var(--c-accent) 16%,var(--c-card))}
.b-c4 em{display:block;font-style:normal;font-size:11px;color:var(--c-accent);text-transform:uppercase;letter-spacing:.1em}
.b-c4 tr:last-child td{border-bottom:0}
.b-c4 .btn{padding:9px 16px;font-size:13px}

.b-c7 .tabs{display:flex;gap:6px;border-bottom:2px solid var(--c-line);margin-bottom:32px;overflow-x:auto}
.b-c7 .tabs b{padding:12px 22px;cursor:pointer;color:var(--c-muted);border-bottom:3px solid transparent;margin-bottom:-2px;white-space:nowrap}
.b-c7 .tabs b.on{color:var(--c-ink);border-color:var(--c-accent)}
.b-c7 .pane{display:grid;grid-template-columns:1.2fr 1fr;gap:44px;align-items:center}
.b-c7 .pane .ph{aspect-ratio:16/10}
.b-c7 h3{font-size:28px;margin-bottom:12px}
.b-c7 p{color:var(--c-muted)}
.b-c7 ul{list-style:none;margin:20px 0 28px;display:grid;gap:8px;font-weight:600}
.b-c7 li::before{content:"→";color:var(--c-accent);margin-right:10px}
@media(max-width:860px){.b-c7 .pane{grid-template-columns:1fr}}

.b-f4 .cols{display:grid;grid-template-columns:1fr 1.5fr;gap:56px;align-items:start}
.b-f4 .sec-head .btn{margin-top:24px}
.b-f4 .tw{overflow-x:auto;border:1px solid var(--c-line);border-radius:var(--radius)}
.b-f4 table{border-collapse:collapse;width:100%;min-width:520px;font-size:15px}
.b-f4 th,.b-f4 td{padding:15px 18px;border-bottom:1px solid var(--c-line);text-align:left}
.b-f4 th{background:var(--c-surface);font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--c-muted)}
.b-f4 tr:last-child td{border-bottom:0}
@media(max-width:860px){.b-f4 .cols{grid-template-columns:1fr}}

.b-a2 .wrap{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.b-a2 .img{aspect-ratio:4/5}
.b-a2 dl{display:grid;gap:4px;margin:8px 0 24px}
.b-a2 dt{font-weight:800;font-size:13px;text-transform:uppercase;letter-spacing:.1em;color:var(--c-accent);margin-top:12px}
.b-a2 dd{color:var(--c-muted)}
.b-a2 .nums{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--c-line);border-bottom:1px solid var(--c-line);margin-bottom:22px}
.b-a2 .nums div{padding:18px 0}
.b-a2 .nums b{font-size:28px;display:block}
.b-a2 .nums span{font-size:13px;color:var(--c-muted)}
@media(max-width:860px){.b-a2 .wrap{grid-template-columns:1fr}}

.b-d1{padding:48px 0 72px}
.b-d1 .wrap{display:grid;grid-template-columns:1.05fr 1fr;gap:56px;align-items:start}
.b-d1 .main{aspect-ratio:1;cursor:zoom-in}
.b-d1 .th{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:12px}
.b-d1 .th i{aspect-ratio:1;border:2px solid transparent;cursor:pointer}
.b-d1 .th i::after{display:none}
.b-d1 .th i.on{border-color:var(--c-accent)}
.b-d1 .crumb{font-size:13px;color:var(--c-muted)}
.b-d1 h1{font-size:clamp(28px,3.2vw,40px);margin:10px 0 14px}
.b-d1 p{color:var(--c-muted)}
.b-d1 dl{display:grid;grid-template-columns:140px 1fr;margin:26px 0;border-top:1px solid var(--c-line)}
.b-d1 dt,.b-d1 dd{padding:12px 0;border-bottom:1px solid var(--c-line);font-size:15px}
.b-d1 dt{color:var(--c-muted)}
.b-d1 dd{font-weight:600}
.b-d1 .acts{display:flex;gap:12px;flex-wrap:wrap}
.b-d1 .tags{display:flex;gap:8px;margin-top:22px;flex-wrap:wrap}
.b-d1 .tags span{font-size:13px;font-weight:700;padding:6px 12px;background:var(--c-surface);border-radius:var(--radius-btn)}
@media(max-width:860px){.b-d1 .wrap{grid-template-columns:1fr}}

.b-d2 .head{display:flex;justify-content:space-between;align-items:baseline;gap:16px;flex-wrap:wrap;margin-bottom:20px}
.b-d2 .tw{overflow-x:auto;background:var(--c-card);border:1px solid var(--c-line);border-radius:var(--radius)}
.b-d2 table{border-collapse:collapse;width:100%;min-width:640px;font-size:15px;font-variant-numeric:tabular-nums}
.b-d2 th,.b-d2 td{padding:14px 18px;border-bottom:1px solid var(--c-line);text-align:left}
.b-d2 th{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--c-muted)}
.b-d2 tr:nth-child(odd) td{background:color-mix(in srgb,var(--c-surface) 60%,transparent)}
.b-d2 tr:last-child td{border-bottom:0}

.b-d8 .wrap{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:56px;align-items:start}
.b-d8 .doc>p{color:var(--c-muted);font-size:17px;margin-bottom:18px}
.b-d8 .doc h3{font-size:22px;margin:34px 0 12px}
.b-d8 figure{margin:26px 0}
.b-d8 figure .ph{aspect-ratio:16/9}
.b-d8 figcaption{font-size:13px;color:var(--c-muted);margin-top:8px}
.b-d8 .vid{aspect-ratio:16/9;margin:8px 0 18px;display:flex;align-items:center;justify-content:center}
.b-d8 .vid b{width:64px;height:64px;border-radius:50%;background:rgba(0,0,0,.55);color:#fff;display:flex;align-items:center;justify-content:center;font-size:22px;position:relative;z-index:1}
.b-d8 table{width:100%;border-collapse:collapse;font-size:15px;margin-bottom:18px}
.b-d8 th,.b-d8 td{border-bottom:1px solid var(--c-line);padding:11px 12px;text-align:left}
.b-d8 th{background:var(--c-surface);font-weight:700}
.b-d8 .side{position:sticky;top:96px}
.b-d8 .form{padding:26px;display:grid;gap:10px;box-shadow:0 16px 40px rgba(0,0,0,.07)}
.b-d8 .form>b{font-size:21px}
.b-d8 .form>p{font-size:13px;color:var(--c-muted);margin-top:-4px}
.b-d8 input,.b-d8 textarea{width:100%;padding:11px 13px;border:1px solid var(--c-line);border-radius:var(--radius-btn);font:inherit;background:var(--c-bg);color:var(--c-ink)}
.b-d8 .btn{justify-content:center}
@media(max-width:900px){.b-d8 .wrap{grid-template-columns:1fr;gap:36px}.b-d8 .side{position:static}}

.b-q1 .wrap{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:start}
.b-q1 details{border-bottom:1px solid var(--c-line);padding:18px 0}
.b-q1 summary{font-weight:700;cursor:pointer;list-style:none;display:flex;justify-content:space-between;gap:16px;font-size:17px}
.b-q1 summary::-webkit-details-marker{display:none}
.b-q1 summary::after{content:"+";color:var(--c-accent);font-size:22px;line-height:1;transition:transform .25s}
.b-q1 details[open] summary::after{transform:rotate(45deg)}
.b-q1 details p{color:var(--c-muted);margin-top:10px}
.b-q1 .form{padding:32px;display:grid;gap:12px;box-shadow:0 20px 50px rgba(0,0,0,.06)}
.b-q1 .form>b{font-size:24px}
.b-q1 .form>p{color:var(--c-muted);font-size:14px;margin-top:-6px}
.b-q1 .two{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.b-q1 input,.b-q1 textarea{width:100%;padding:12px 14px;border:1px solid var(--c-line);border-radius:var(--radius-btn);font:inherit;background:var(--c-bg);color:var(--c-ink)}
.b-q1 .up{font-size:14px;color:var(--c-accent);font-weight:700;cursor:pointer}
.b-q1 .btn{justify-content:center}
@media(max-width:860px){.b-q1 .wrap{grid-template-columns:1fr}}

.b-t6 .wrap{display:grid;grid-template-columns:1.1fr 1fr;gap:64px;align-items:center}
.b-t6 .avs{display:flex;align-items:center;margin-top:30px}
.b-t6 .avs i{width:46px;height:46px;border-radius:50%;border:3px solid var(--c-surface);margin-left:-10px;background:var(--c-accent);color:var(--c-on-accent);display:flex;align-items:center;justify-content:center;font-style:normal;font-weight:800}
.b-t6 .avs i:first-child{margin-left:0}
.b-t6 .avs i:nth-child(2n){background:var(--c-primary);color:var(--c-on-primary)}
.b-t6 .avs span{margin-left:14px;font-weight:700;color:var(--c-muted);font-size:14px}
.b-t6 .phone{justify-self:center;width:320px;border-radius:40px;border:10px solid #15171c;background:#ececec;overflow:hidden;box-shadow:0 30px 70px rgba(0,0,0,.25)}
.b-t6 .bar{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;background:#f6f6f6;font-size:14px;border-bottom:1px solid #ddd}
.b-t6 .chat{padding:16px 12px 26px;display:grid;gap:12px;min-height:380px}
.b-t6 .chat p{display:flex;align-items:flex-start;gap:8px;font-size:14px;margin:0}
.b-t6 .chat p.r{justify-content:flex-end}
.b-t6 .chat i{width:34px;height:34px;border-radius:6px;flex:none;background:repeating-conic-gradient(#333 0 25%,#fff 0 50%) 0 0/8px 8px}
.b-t6 .chat p.r i{background:var(--c-accent)}
.b-t6 .chat span{background:#fff;padding:8px 11px;border-radius:6px;max-width:200px;color:#111}
.b-t6 .chat p.r span{background:#95ec69}
@media(max-width:860px){.b-t6 .wrap{grid-template-columns:1fr}.b-t6 .phone{width:280px}}

.b-q5{background:var(--c-accent);color:var(--c-on-accent);padding:88px 0}
.b-q5 .wrap{display:grid;grid-template-columns:1fr 1.15fr;gap:48px;align-items:start}
.b-q5 .form{padding:34px;display:grid;gap:14px;color:var(--c-ink);border:0}
.b-q5 .form b{font-size:24px}
.b-q5 input,.b-q5 textarea{width:100%;padding:12px 2px;border:0;border-bottom:1px solid var(--c-line);font:inherit;background:transparent;color:var(--c-ink)}
.b-q5 .row{display:flex;justify-content:space-between;align-items:center;margin-top:6px}
.b-q5 .up{border:1px solid var(--c-accent);color:var(--c-accent);border-radius:999px;padding:7px 16px;font-size:14px;font-weight:700;cursor:pointer}
.b-q5 .faq>h2{font-size:clamp(30px,3.4vw,44px)}
.b-q5 .faq>p{opacity:.85;margin:8px 0 22px}
.b-q5 details{background:var(--c-card);color:var(--c-ink);border-radius:22px;margin-bottom:12px;padding:16px 20px}
.b-q5 summary{list-style:none;display:flex;align-items:center;gap:14px;cursor:pointer;font-weight:700}
.b-q5 summary::-webkit-details-marker{display:none}
.b-q5 summary em{font-style:normal;font-size:13px;color:var(--c-muted);flex:none}
.b-q5 summary span{flex:1}
.b-q5 summary i{width:34px;height:34px;border-radius:50%;background:var(--c-surface);flex:none;position:relative;transition:.25s}
.b-q5 summary i::after{content:"↓";position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-style:normal;color:var(--c-muted)}
.b-q5 details[open] summary i{background:var(--c-accent);transform:rotate(180deg)}
.b-q5 details[open] summary i::after{color:var(--c-on-accent)}
.b-q5 details p{margin:10px 0 0 44px;color:var(--c-muted);font-size:15px}
@media(max-width:860px){.b-q5 .wrap{grid-template-columns:1fr}.b-q5 .form{order:2}}

.b-x01{position:relative;height:660px;overflow:hidden;color:#fff;background:#111}
.b-x01 .sl{position:absolute;inset:0;display:flex;align-items:center;opacity:0;visibility:hidden;transition:opacity 1s,visibility 1s}
.b-x01 .sl.on{opacity:1;visibility:visible;z-index:1}
.b-x01 .bg{position:absolute;inset:0;border-radius:0;transform:scale(1.1);transition:transform 7s linear}
.b-x01 .sl.on .bg{transform:scale(1)}
.b-x01 .sl::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,rgba(0,0,0,.72),rgba(0,0,0,.12) 75%)}
.b-x01 .sl .wrap{position:relative;z-index:2;width:100%}
.b-x01 .sl .wrap>*{opacity:0;transform:translateY(26px);transition:opacity .8s,transform .8s}
.b-x01 .sl.on .wrap>*{opacity:1;transform:none}
.b-x01 .sl.on .wrap>:nth-child(2){transition-delay:.15s}.b-x01 .sl.on .wrap>:nth-child(3){transition-delay:.3s}.b-x01 .sl.on .wrap>:nth-child(4){transition-delay:.45s}
.b-x01 .eyebrow{color:#fff;opacity:.85}
.b-x01 h1,.b-x01 h2{font-size:clamp(34px,5vw,64px);max-width:760px;margin:14px 0 18px}
.b-x01 p{font-size:19px;max-width:560px;opacity:.88}
.b-x01 .acts{display:flex;gap:14px;margin-top:30px;flex-wrap:wrap}
.b-x01 .ctl{position:absolute;left:0;right:0;bottom:36px;z-index:3;display:flex;justify-content:space-between;align-items:center}
.b-x01 .nums{display:flex;align-items:center;gap:14px;font:700 14px var(--font-head)}
.b-x01 .bar{width:160px;height:2px;background:rgba(255,255,255,.3);overflow:hidden}
.b-x01 .bar em{display:block;height:100%;width:100%;background:var(--c-accent);transform-origin:left;transform:scaleX(0)}
.b-x01 .bar em.run{animation:x01bar 6s linear forwards}
@keyframes x01bar{to{transform:scaleX(1)}}
.b-x01 .arr{display:flex;gap:10px}
.b-x01 .arr button{width:48px;height:48px;border-radius:50%;border:1px solid rgba(255,255,255,.5);background:transparent;color:#fff;font-size:18px;cursor:pointer;transition:.2s}
.b-x01 .arr button:hover{background:#fff;color:#111}
@media(max-width:700px){.b-x01{height:560px}.b-x01 .sl::before{background:rgba(0,0,0,.55)}.b-x01 .arr{display:none}}

