(function(){
  var sel='section:not(:first-of-type) .sec-head,.grid>*,.row,.wall>*,.steps>*,.mosaic>*,.mas>*,.pane,.tw,.line>*,.box';
  var els=[].slice.call(document.querySelectorAll(sel));
  if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  els.forEach(function(el){
    if(el.closest('.b-h1,.b-h2,.b-h3,.b-h4,.b-h5,.b-h6,.b-h7,.b-h8,.b-d1,[class^="b-x"]'))return;
    var i=[].indexOf.call(el.parentNode.children,el);
    el.classList.add('m-fu');el.style.transitionDelay=Math.min(i,5)*90+'ms';
  });
  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:.15});
  document.querySelectorAll('.m-fu').forEach(function(el){io.observe(el)});
})();

(function(){
  var els=document.querySelectorAll('.b-t1 b,.b-h6 .stats b,.b-a2 .nums b');
  if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  function run(el){
    var raw=el.dataset.raw||el.textContent;el.dataset.raw=raw;
    var m=raw.match(/^([^0-9]*)([0-9][0-9,.]*)(.*)$/);if(!m)return;
    var n=parseFloat(m[2].replace(/,/g,''));if(n>=1900&&n<=2100&&m[2].indexOf(',')<0)return;
    var dec=(m[2].split('.')[1]||'').length,comma=m[2].indexOf(',')>-1,t0=performance.now();
    (function f(t){var p=Math.min(1,(t-t0)/1400),v=(n*(1-Math.pow(1-p,3))).toFixed(dec);
      if(comma)v=Number(v).toLocaleString('en-US',{minimumFractionDigits:dec});
      el.textContent=m[1]+v+m[3];if(p<1)requestAnimationFrame(f)})(t0);
  }
  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){run(e.target);io.unobserve(e.target)}})},{threshold:.5});
  els.forEach(function(el){io.observe(el)});
})();

(function(){
  if(matchMedia('(prefers-reduced-motion: reduce)').matches||innerWidth<768)return;
  var bgs=document.querySelectorAll('.b-h2 .bg,.b-h8 .bg');
