  function clean(s){return (s||'').replace(/\s+/g,' ').trim().slice(0,30)}
  function open(btn){last=btn;var sec=btn.closest('section,header,footer,div[class^="b-"]'),title=btn.querySelector('b,h3,.hd');
    var t=clean((title||btn).textContent),h=sec&&sec.querySelector('h1,h2,h3'),hs=h?clean(h.textContent):'页面';
    src.value=(title?'产品：'+t:'按钮：'+t)+' @ '+hs;tip.textContent='来自「'+hs+'」· 我们会在 12 小时内回复您';
